// function filterBy(arr, predicate) mein array aur function do
// Agar array nahi: []
// Agar function nahi: []
// Warna filter karo

solution:
function filterBy(arr, predicate) {
  if (!Array.isArray(arr)) return []
  if (typeof predicate !== "function") return []
  return arr.filter(predicate)
}
